        require(address(this).balance >= depositAmt);
        c.SetLogFile(address(this));
        c.SetMinSum(0);
        c.Deposit{value: depositAmt}();
        uint balBefore = c.balances(address(this));
        uint cbalBefore = address(c).balance;
        bool ok = false;
        uint selfBefore = address(this).balance;
        (bool s, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amount));
        require(s);
        ok = true;
        uint balAfter = c.balances(address(this));
        uint cbalAfter = address(c).balance;
        assert(ok && balBefore - balAfter == amount && cbalBefore - cbalAfter == amount && address(this).balance - selfBefore == amount);
    }
    receive() external payable {}
    function AddMessage(address, uint, string calldata) external payable {}
}

