contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    bool public reject;
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        c.SetMinSum(0);
        c.Deposit{value: amount}();
        uint beforeBal = c.balances(address(this));
        uint beforeEth = address(c).balance;
