contract InvMutTest {
    C c;
    constructor(C _c) payable { c = _c; }
    function run(uint m, uint d, uint a) public payable {
        require(address(this).balance >= d);
        c.SetMinSum(m);
        c.Deposit{value: d}();
        uint b0 = c.balances(address(this));
        uint ms = c.MinSum();
        bool reverted;
        try c.Collect(a) { reverted = false; } catch { reverted = true; }
        uint b1 = c.balances(address(this));
        assert(reverted == !(b0 >= ms && b0 >= a) && (reverted ? (b1 == b0) : (b1 == b0 - a)));
    }
    receive() external payable {}
}
